import test from 'node:test';import assert from 'node:assert/strict';import {createBoardFlow} from '../src/pixi/board-flow.js';import {productionBoardFlowOptions} from '../src/app/production-board-profile.js';import {installSourceLeftResidual} from '../src/pixi/source-left-residual.js';import {sourceBoardSurfaces} from '../src/pixi/source-board-surfaces.js';
const make=()=>{const p=createBoardFlow({lcd:true,...productionBoardFlowOptions()}).flow.physics;p.pins.find(p=>p.id===33).x=75.25;delete p.colliders.find(c=>c.sourceGuideId==='left-title-edge'&&c.sourceGuideSegment===0).excludeCapA;return p;};
test('left residual trial changes only the permitted pin33 and the connected guide endpoint cap',()=>{const p=make(),pins=structuredClone(p.pins),art=sourceBoardSurfaces(p),colliders=JSON.parse(JSON.stringify(p.colliders));installSourceLeftResidual(p);for(const expected of pins){if(expected.id===33)expected.x-=3;}assert.deepEqual(p.pins,pins);assert.deepEqual(sourceBoardSurfaces(p),art);colliders.find(c=>c.sourceGuideId==='left-title-edge'&&c.sourceGuideSegment===0).excludeCapA=true;assert.equal(JSON.stringify(p.colliders),JSON.stringify(colliders));assert.equal(p.ballRadius,3);assert.equal(p.pockets.find(p=>p.kind==='start').w,16);});
test('both recorded upper-left rest states leave the joint under gravity with no speed injection',()=>{for(const[x,y]of[[180.20506343112493,342.33130818602194],[187.8188882133046,337.74564008204436]]){const p=make();installSourceLeftResidual(p);const b={id:1,x:x*.5-14,y:y*.5+120,vx:0,vy:0,r:3,omega:0,hits:0,contactCount:0,leftLaunchPlane:true,sourceStageSpilled:true};for(let i=0;i<3600;i++)p.advanceBall(b,1/1200);assert.ok((b.y-120)*2>500);}});
